/// `armv7ve`: the architecture rsasm's ARM backend is, and
/// what `tools/xas-diff` and `tools/mc-diff` assemble the
/// reference as.
pub const DEFAULT_ARCH: usize = 32;

/// `neon-vfpv4`: the unit it has, likewise.
pub const DEFAULT_FPU: usize = 28;

/// `fpu_any`, the bits a `.fpu` takes away from the
/// selection before adding the unit's own.
pub const FPU_ANY: Set = [0x0, 0xfffffff200000000];

// The single bits a hand-written encoder asks about, because
// GNU as's own encoder does: which instruction sets the
// target has at all, which `nop` it spells, whether `swp` is
// still allowed, and whether `msr` and `mrs` reach the banked
// registers.
pub const V1: Set = [0x1, 0x0];
pub const V4T: Set = [0x40, 0x0];
pub const V6K: Set = [0x2000, 0x0];
pub const V6T2: Set = [0x8000, 0x0];
pub const V6_DSP: Set = [0x4000000, 0x0];
pub const V8: Set = [0x4000, 0x0];
pub const VIRT: Set = [0x80000000, 0x0];

/// The features GNU as's `known_t32_only_insn` reads as
/// saying a mnemonic's Thumb encoding is 32 bits wide and
/// always has been, so that it needs no Thumb-2.
pub const WIDE_ONLY: Set = [0x5c03010000, 0x0];

/// `ARM_ANY`: every core feature, which is what
/// `-march=all` selects and which GNU as's `check_obsolete`
/// lets an obsolete instruction through under.
pub const ANY: Set = [0xffcfffffffffffff, 0xffffffff];
